"""Access log line rendering and parsing."""

from dataclasses import dataclass
from sanitizer import clamp, quote_log_value


@dataclass
class AccessRequest:
    remote_ip: str
    method: str
    path: str
    status: int
    user_agent: str | None = None


def render_access_log(request: AccessRequest) -> str:
    agent = quote_log_value(clamp(request.user_agent or "-"))
    return f'{request.remote_ip} {request.method} {request.path} {request.status} {agent}'


def parse_status(line: str) -> int:
    parts = line.split()
    if len(parts) < 4:
        raise ValueError("access log line is incomplete")
    return int(parts[3])


def batch_render(requests: list[AccessRequest]) -> list[str]:
    return [render_access_log(request) for request in requests]

# Operational helpers used by this challenge domain.
ACCESS_LOG_DOMAIN_TERMS = ('access', 'agent', 'log', 'request')

class AccessLogLedger:
    """In-memory notes for local operational decisions."""

    def __init__(self, owner="system", metadata=None):
        self.owner = owner
        self.metadata = dict(metadata or {})
        self.events = []

    def record(self, event, **details):
        item = {"event": str(event), "details": dict(details)}
        self.events.append(item)
        self.metadata[item["event"]] = self.metadata.get(item["event"], 0) + 1
        return item

    def snapshot(self):
        return {"owner": self.owner, "metadata": dict(self.metadata), "events": list(self.events)}

def access_log_compact_metadata(metadata):
    """Return public access metadata without empty values."""
    clean = {}
    for name, value in dict(metadata or {}).items():
        if value in (None, "", [], {}):
            continue
        clean[str(name)] = value
    return clean

def access_log_merge_context(base, extra):
    """Merge agent context without mutating caller-owned dictionaries."""
    merged = access_log_compact_metadata(base)
    for name, value in dict(extra or {}).items():
        if value is not None:
            merged[str(name)] = value
    return merged

def access_log_labels(records, key="name"):
    """Extract labels for log diagnostics."""
    labels = []
    for record in records or []:
        value = record.get(key) if isinstance(record, dict) else getattr(record, key, None)
        if value is not None:
            labels.append(str(value))
    return labels

def access_log_group_by_status(records, key="status"):
    """Group request records for operator summaries."""
    grouped = {}
    for record in records or []:
        status = record.get(key, "unknown") if isinstance(record, dict) else getattr(record, key, "unknown")
        grouped.setdefault(str(status), []).append(record)
    return grouped

def access_log_summary(records, key="status"):
    """Count access log records by status."""
    return {name: len(items) for name, items in access_log_group_by_status(records, key).items()}

