"""Sanitizers for request metadata that appears in logs."""

CONTROL_REPLACEMENT = " "


def clean_header_value(value: str | None) -> str:
    if value is None:
        return "-"
    text = str(value).replace("\t", CONTROL_REPLACEMENT)
    return text.strip()


def clamp(value: str, limit: int = 240) -> str:
    text = str(value)
    if len(text) <= limit:
        return text
    return text[: limit - 1] + "…"


def quote_log_value(value: str | None) -> str:
    cleaned = clean_header_value(value)
    return '"' + cleaned.replace('"', "'") + '"'

